            [{ inReplyToId: 77, reply: 'Fixed.' }]);
        assert.equal(coverage.openCount, 1, 'rootCommentId alone makes a thread addressable');
        assert.equal(coverage.unaddressed.length, 0);
        assert.equal(coverage.unaddressable.length, 0);
    });
});

