        return {
            blocked: true,
            result: handleReworkBlocked(scm, tracker, pr, ticketKey, statuses, fixSummary,
                replyCoverage.openCount, actualParams, replyCoverage.unaddressed,
                replyCoverage.unaddressable, replyCoverage.totalOpenCount)
